CREATE PROCEDURE [dbo].[sp_Update_Check_Discounts] AS /** ## Procedure Name       *[toast].[dbo].[sp_Update_Check_Discounts]*   **Procedure Type**      *function / stored procedure*   **Author**              Wilson, Don < dwilson@newks.com >   **Version**             1   **Created**             YYYYMMDD   **Report Name**         *< name of report >*   **Summary**   *summary of report*      ### Parameters   ```sql   StartDate date              Start date of the range   EndDate date                End Date of the range   StoreGrouping int           The grouping type of stores   StoreGroup varchar(1500)    The store / store group / dma / etc to run for   ```      ### Output    *describe the fields of the result set   (if code is in this description, block the code with three backticks on a blank line above and below the code block.   After the first tripple backtick, place the name of the language the code is written in.   See the example of this in the Parameters section above.  Follow the second tuple with a blank line.*      ### Change History   **Change Date:**            *YYYYMMDD*   **Author:**                 *Last, First < email address >*   **Version**:                ##   **Change:**   *detail change here*      -------------------     **/ BEGIN     -- SET NOCOUNT ON added to prevent extra result sets from     -- interfering with SELECT statements.     SET NOCOUNT ON;      declare          -- If this is for a table build, then Tab, if not, then Proc 	    @RunType varchar(4) = 'Proc'          -- The time the procedure begins running 	   ,@StartTime datetime = getdate()        -- The database the procedure is running in 	   ,@DBName varchar(150) = DB_NAME()        -- The name of the procedure itself 	   ,@ProcName varchar(150) = OBJECT_NAME(@@PROCID)        -- Default the error information to no error 	   ,@ErrorNumber int = 0 	   ,@ErrorMessage varchar(250) = '' 	   ,@ErrorLine int = 0             BEGIN TRY                 -- if this is a table build, perform it as a transaction         if (@RunType = 'Tab') begin transaction;  		declare @Params varchar(2000) = (select '' as Params for json path)      	select 			StoreID,  			DateOfBusiness,  			OrderID, 			CheckID, 			sum(NonTaxDiscountAmount) Discount 		into #CheckDiscounts 		from toast.dbo.hstAppliedDiscounts 		group by StoreID, DateOfBusiness, OrderID, CheckID  		update toast.dbo.hstCheck set 			DiscountAmount = cd.Discount 		from toast.dbo.hstCheck c 		join #CheckDiscounts cd 		on c.StoreID = cd.StoreID 		and c.DateOfBusiness = cd.DateOfBusiness 		and c.OrderID = cd.OrderID 		and c.CheckID = cd.CheckID  		drop table #CheckDiscounts                  -- If the table build has no error, then commit the transaction 		if (@RunType = 'Tab') commit transaction;                          -- Log the successful completion         exec Logging.dbo.Write_Procedure_Execution              @RunType = @RunType             ,@StartTime = @StartTime             ,@DBName = @DBName             ,@ProcName = @ProcName 			,@Params = @Params;                  END TRY     BEGIN CATCH         -- If there are errors and a transaction was started, roll it back         IF @@TRANCOUNT > 0         ROLLBACK TRANSACTION;                  -- Record the error details         set @ErrorNumber  = ERROR_NUMBER();         set @ErrorLine  = ERROR_LINE();         set @ErrorMessage  = ERROR_MESSAGE();                  -- Log the error         exec Logging.dbo.Write_Procedure_Execution              @RunType = @RunType             ,@StartTime = @StartTime             ,@DBName = @DBName             ,@ProcName = @ProcName             ,@ErrorNumber = @ErrorNumber             ,@ErrorMessage = @ErrorMessage             ,@ErrorLine = @ErrorLine 			,@Params = @Params;         THROW;     END CATCH END